update t_tal
set tal_matched_score = #{score}, tal_updated_at = now()
where tal_id = #{talId}

update t_tal
set tal_status = #{status}, tal_updated_at = now()
where tal_id = #{talId}

mapper.select:
select pos_id as positionId, pos_title as title, date_format(pos_updated_at, '%Y-%m-%d %H:%i:%s') as positionVersion, pos_experience_required as experience,
       pos_education_required as education, cast(pos_jd_json as char) as description
from t_pos where pos_id = #{positionId} and pos_company_id = #{companyId}

select cast(asr_report as char) as report, date_format(asr_updated_at, '%Y-%m-%d %H:%i:%s') as generatedAt
from t_ai_candidate_analysis where asr_company_id = #{companyId} and asr_position_id = #{positionId}
  and asr_candidate_id = #{talId}

select cast(asr_report as char) as report, date_format(asr_updated_at, '%Y-%m-%d %H:%i:%s') as generatedAt
from t_ai_candidate_analysis where asr_company_id = #{companyId} and asr_candidate_id = #{talId}
order by asr_updated_at desc, asr_position_id desc limit 1

